/** Every palette, in the order the settings screen lists them. */
internal val KoalaPalettes: Map<PaletteId, Pair<KoalaColors, KoalaColors>> = mapOf(
    PaletteId.EUCALYPTUS to (KoalaEucalyptusDarkColors to KoalaEucalyptusLightColors),
    PaletteId.FJORD to (KoalaFjordDarkColors to KoalaFjordLightColors),
    PaletteId.EMBER to (KoalaEmberDarkColors to KoalaEmberLightColors),
    PaletteId.LAVENDER to (KoalaLavenderDarkColors to KoalaLavenderLightColors),
    PaletteId.AURORA to (KoalaAuroraDarkColors to KoalaAuroraLightColors),
    PaletteId.SANDSTONE to (KoalaSandstoneDarkColors to KoalaSandstoneLightColors),
    PaletteId.OBSIDIAN to (KoalaObsidianDarkColors to KoalaObsidianLightColors),
    PaletteId.PAPER to (KoalaPaperDarkColors to KoalaPaperLightColors),
    PaletteId.ULTRAVIOLET to (KoalaUltravioletDarkColors to KoalaUltravioletLightColors),
)

/** The colours for one palette in one mode. */
fun koalaColors(palette: PaletteId, dark: Boolean): KoalaColors {
    val pair = KoalaPalettes[palette] ?: KoalaPalettes.getValue(PaletteId.DEFAULT)
    return if (dark) pair.first else pair.second
}
